    uni_ucd_desc: "Το μεγαλύτερο πανεπιστήμιο της Ιρλανδίας και μέλος του διακεκριμένου δικτύου Research Universities Ireland, με πάνω από 500 προγράμματα σε όλους τους κλάδους.",
