    uni_mtu_desc: "MTU нь Cork IT болон IT Tralee-гийн давуу талыг хослуулан, салбартай хамтын ажиллагаа, инновацид хүчтэй анхаарал хандуулсан хэрэглээний хөтөлбөрүүдийг санал болгодог.",
