    uni_tus_desc: "TUS нь Ирландын дундад, төв баруун бүсийн технологийн их сургууль бөгөөд Shannon бүс нутгийн салбартай хүчтэй холбоотой карьерт чиглэсэн хөтөлбөрүүд санал болгодог.",
